export function step(state, dt) {
  const { ball, paddle } = state;
  const px = ball.x;
  const py = ball.y;

  // Sub-stepped movement: MAX_STEP is derived from the grid geometry so that
  // no brick can be jumped over (tunneling) nor crossed past its midline
  // between two collision samples (which would misattribute the hit face).
  // The bounce budget lives here, for the whole pass: one bounce per axis.
  const bounced = { x: false, y: false };
  const total = Math.hypot(ball.vx * dt, ball.vy * dt);
  const steps = Math.max(1, Math.ceil(total / MAX_STEP));
  const h = dt / steps;
  for (let i = 0; i < steps; i++) {
    ball.x += ball.vx * h;
    ball.y += ball.vy * h;
    resolveBricks(state, bounced);
  }

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle — swept test: bounce when the ball's bottom edge crosses the top
  // of the paddle band during this pass, even if no sample lands inside it
  // (a fast ball would otherwise skip the 12px band between two samples).
  const bottom0 = py + ball.r;
  const bottom1 = ball.y + ball.r;
  if (
    ball.vy > 0 &&
    bottom0 < paddle.y + paddle.h &&
    bottom1 > paddle.y
  ) {
    const t = Math.max(0, (paddle.y - bottom0) / (bottom1 - bottom0));
    const xAtHit = px + (ball.x - px) * t;
    if (xAtHit >= paddle.x && xAtHit <= paddle.x + paddle.w) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      // Keep the rebound at the level speed (D7): rewrite vx without
      // renormalizing lets the ball accelerate with every paddle hit.
      const norm = Math.hypot(ball.vx, ball.vy);
      if (norm > 0) {
        const scale = ballSpeed(state.level) / norm;
        ball.vx *= scale;
        ball.vy *= scale;
      }
      state.combo = 0; // touching the paddle resets the combo
    }
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}
```

