// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The missing bounce in frame() is what lets the ball plow
// straight through bricks (see #1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

edits.newText:
// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The face is derived during resolution in step() from
// the penetration depths (smallest wins, ties are corners).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Brick collision resolution (pure logic, exercised through step()) -----

// Maximum distance the ball may travel between two brick-collision samples.
// Derived from the grid geometry: a step larger than BRICK_H + 2*BALL_R (34px)
// could jump a whole brick (tunneling), and a step larger than BRICK_H / 2
// could cross a brick's midline between two samples and misattribute the hit
// face to the far side. BRICK_H / 2 = 10 binds.
const MAX_STEP = BRICK_H / 2;

// Resolves collisions with every live brick the ball currently overlaps.
// `bounced` carries the per-pass budget (one velocity flip per axis) so that
// a ball overlapping two bricks on a grid seam bounces once instead of twice
// (two flips would cancel and the ball would sail through the seam).
// Each resolved brick is destroyed and scored exactly once.
function resolveBricks(state, bounced) {
  const { ball, bricks } = state;
  const EPS = 1e-6; // corner tie tolerance: equal penetration on both axes

  for (let guard = 0; guard < bricks.length + 1; guard++) {
    let best = null;

    for (const brick of bricks) {
      if (!brick.alive || !collides(ball, brick)) continue;

      // Penetration depth per face of the brick's box.
      const left = ball.x + ball.r - brick.x;
      const right = brick.x + brick.w - (ball.x - ball.r);
      const top = ball.y + ball.r - brick.y;
      const bottom = brick.y + brick.h - (ball.y - ball.r);

      // The hit face is the one with the smallest penetration; equal
      // penetration on both axes means a corner (both axes are reversed).
      const minX = Math.min(left, right);
      const minY = Math.min(top, bottom);
      let face;
      if (Math.abs(minX - minY) <= EPS) face = 'corner';
      else if (minX < minY) face = left < right ? 'left' : 'right';
      else face = top < bottom ? 'top' : 'bottom';

      // Only bounce off a face the ball is moving INTO; a brick the ball is
      // merely leaving must not reverse its velocity (ghost-collision guard).
      let approached;
      if (face === 'left') approached = ball.vx > 0;
      else if (face === 'right') approached = ball.vx < 0;
      else if (face === 'top') approached = ball.vy > 0;
      else if (face === 'bottom') approached = ball.vy < 0;
      else approached = ball.vx !== 0 || ball.vy !== 0; // corner: any motion counts

      if (!best || (approached && !best.approached)) {
        best = { brick, face, approached };
      }
    }

    if (!best) break;

    best.brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(best.brick, state.combo);

    if (best.face === 'top') {
      if (!bounced.y) { ball.vy = Math.abs(ball.vy); bounced.y = true; }
      ball.y = best.brick.y - ball.r;
    } else if (best.face === 'bottom') {
      if (!bounced.y) { ball.vy = -Math.abs(ball.vy); bounced.y = true; }
      ball.y = best.brick.y + best.brick.h + ball.r;
    } else if (best.face === 'left') {
      if (!bounced.x) { ball.vx = Math.abs(ball.vx); bounced.x = true; }
      ball.x = best.brick.x - ball.r;
    } else if (best.face === 'right') {
      if (!bounced.x) { ball.vx = -Math.abs(ball.vx); bounced.x = true; }
      ball.x = best.brick.x + best.brick.w + ball.r;
    } else {
      // corner: reverse both axes (once per axis per pass) and push the
      // ball diagonally out of the brick.
      if (!bounced.x) { ball.vx = -ball.vx; bounced.x = true; }
      if (!bounced.y) { ball.vy = -ball.vy; bounced.y = true; }
      const b = best.brick;
      ball.x = ball.x < b.x + b.w / 2 ? b.x - ball.r : b.x + b.w + ball.r;
      ball.y = ball.y < b.y + b.h / 2 ? b.y - ball.r : b.y + b.h + ball.r;
    }
  }
}

