// neon.test.js — PARTIAL coverage (on purpose).
//
// What is covered today: the collision primitive and a couple of physics
// bounces. What is NOT covered yet: score and combo (see ISSUES.md #5), nor
// level progression. This is a starting point for the testing work ahead, not
// a complete suite.
//
// Run: `node --test "game/**/*.test.js"`  (or `npm test`)

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  ballSpeed,
  UP,
  DOWN,
  LEFT,
  RIGHT,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: belowField(), r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// --- Brick bounces (regression suite for the playtest ticket) --------------
// The ball used to plow straight through bricks (no bounce, no push-out).
// These cases pin the per-face bounce, the push-out, the corner rule, the
// grid-seam guard, the anti-tunneling sub-step and the paddle sweep.

const SPEED = ballSpeed(1);

// Brick (row 0, col 0) of a fresh level-1 grid: x in [4, 76], y in [48, 68].
const BRICK0 = { x: 4, y: 48, w: 72, h: 20 };

// D1: the reported symptom — a ball reaching a brick must bounce off it.
test('brick bounce: ball hitting the bottom face is reflected down', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball = { x: 40, y: 75, r: 7, vx: 0, vy: -SPEED }; // tangent below, rising
  step(state, 1 / 60);
  assert.equal(brick.alive, false, 'brick is destroyed');
  assert.equal(Math.sign(state.ball.vy), DOWN, 'bounced back down, away from the brick');
  assert.ok(state.ball.y - state.ball.r >= brick.y + brick.h, 'ball left below the brick');
});

// D2: a bounce must reposition the ball out of the brick, or it sticks and
// re-inverts every frame.
test('brick bounce: ball is pushed out of the brick (no sticking)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball = { x: 40, y: 41, r: 7, vx: 0, vy: SPEED }; // falling into the top face
  step(state, 1 / 60);
  assert.equal(brick.alive, false);
  assert.equal(Math.sign(state.ball.vy), UP, 'bounced back up');
  assert.ok(state.ball.y + state.ball.r <= brick.y, 'ball repositioned above the brick');
});

// D3a: the axis that bounces is the axis of smallest penetration.
test('brick bounce: side hit flips vx only, not vy', () => {
  const state = createState(1);
  const brick = state.bricks[2]; // col 2: x in [164, 236]
  state.ball = { x: 156, y: 58, r: 7, vx: SPEED, vy: 0 };
  step(state, 1 / 60);
  assert.equal(brick.alive, false);
  assert.equal(Math.sign(state.ball.vx), LEFT, 'horizontal velocity reversed');
  assert.equal(state.ball.vy, 0, 'vertical velocity untouched by a side hit');
  assert.ok(state.ball.x + state.ball.r <= brick.x, 'ball pushed back to the left of the brick');
});

// D3b: equal penetration on both axes is a corner: both velocities reverse.
test('brick bounce: corner hit (equal penetration) reverses BOTH axes', () => {
  const state = createState(1);
  const brick = state.bricks[3]; // col 3: x in [244, 316]
  state.ball = { x: 240.5, y: 44.5, r: 7, vx: 200, vy: 200 }; // on the corner diagonal
  step(state, 1 / 60);
  assert.equal(brick.alive, false);
  assert.equal(Math.sign(state.ball.vx), LEFT);
  assert.equal(Math.sign(state.ball.vy), UP);
});

// D4: a ball straddling the seam between two adjacent bricks must bounce
// once — two per-brick flips would cancel and the ball would pass through.
test('brick bounce: grid seam reflects the ball exactly once', () => {
  const state = createState(1);
  const b0 = state.bricks[2]; // [164, 236]
  const b1 = state.bricks[3]; // [244, 316]
  state.ball = { x: 240, y: 58, r: 7, vx: -100, vy: 0 }; // straddles the 236-244 seam
  step(state, 1 / 60);
  assert.equal(b0.alive, false);
  assert.equal(b1.alive, false);
  assert.ok(state.ball.vx > 0, 'one bounce per axis per pass: ball heads back right');
});

// D5: anti-tunneling. At level 6 the max step (710 * 0.05 = 35.5px) exceeds
// brick height + ball diameter (34px): a single sample could skip the brick.
test('brick bounce: no tunneling at level 6 (step 35.5px > brick 34px)', () => {
  const state = createState(6);
  const brick = state.bricks[0];
  state.ball = { x: 40, y: 75, r: 7, vx: 0, vy: -ballSpeed(6) };
  step(state, 0.05);
  assert.equal(brick.alive, false, 'the crossed brick is destroyed');
  assert.equal(Math.sign(state.ball.vy), DOWN, 'ball bounced off the bottom face');
  assert.ok(state.ball.y - state.ball.r >= brick.y + brick.h, 'ball never got above the brick');
});

// D6a: the paddle band is 12px; a level-2 ball falls 17.5px per capped step
// and must still bounce off the paddle (swept test, not a single sample).
test('paddle: fast falling ball does not skip the paddle band (level 2)', () => {
  const state = createState(2);
  state.ball = { x: 320, y: 440, r: 7, vx: 0, vy: ballSpeed(2) };
  step(state, 0.05);
  assert.equal(Math.sign(state.ball.vy), UP, 'bounced off the paddle');
  assert.ok(state.ball.y + state.ball.r <= state.paddle.y, 'ball ends up above the paddle');
});

// D6b: a ball that starts below the paddle must NOT bounce (it is lost).
test('paddle: ball already below the paddle does not bounce', () => {
  const state = createState(2);
  state.ball = { x: 320, y: 470, r: 7, vx: 0, vy: ballSpeed(2) }; // bottom 477 > 460
  const lost = step(state, 0.05);
  assert.equal(lost, true, 'ball is lost');
  assert.equal(Math.sign(state.ball.vy), DOWN, 'no bounce once below the paddle');
});

// D7: the paddle rebound must conserve the level speed (no unbounded
// acceleration across exchanges).
test('paddle: rebound conserves the level speed', () => {
  const state = createState(1);
  state.ball = { x: 344, y: 440, r: 7, vx: 0, vy: SPEED }; // hit = (344-320)/48 = 0.5
  step(state, 1 / 60);
  const speed = Math.hypot(state.ball.vx, state.ball.vy);
  assert.ok(Math.abs(speed - SPEED) < 0.01, `speed ${speed} must equal ${SPEED}`);
});

